import java.util.*;

class Solution {
  public int minimumChanges(String s, int k) {
    int n = s.length(), INF = 1 << 29;
    int[][] cost = new int[n][n];
    for (int l = 1; l <= n; l++)
      for (int i = 0; i + l <= n; i++) {
        int j = i + l - 1, best = INF;
        for (int d = 1; d < l; d++)
          if (l % d == 0) {
            int c = 0;
            for (int a = i; a < i + d; a++)
              for (int x = a, y = a + l - d; x < y; x += d, y -= d)
                if (s.charAt(x) != s.charAt(y)) c++;
            best = Math.min(best, c);
          }
        cost[i][j] = best;
      }
    int[][] dp = new int[k + 1][n + 1];
    for (int[] a : dp) Arrays.fill(a, INF);
    dp[0][0] = 0;
    for (int p = 1; p <= k; p++)
      for (int i = p; i <= n; i++)
        for (int q = p - 1; q < i; q++)
          dp[p][i] = Math.min(dp[p][i], dp[p - 1][q] + cost[q][i - 1]);
    return dp[k][n];
  }
}
